// Shared helpers for the browser end-to-end scripts in this folder.
const { chromium } = require('playwright');
const path = require('path');

const BASE = process.env.BASE || 'http://127.0.0.1:8080/web/';
const OUT = process.env.OUT || path.join(__dirname, 'out');
// Fixtures are generated by web_e2e.sh into FIXTURES.
const FIXTURES = process.env.FIXTURES || path.join(__dirname, 'fixtures');
const SONG = path.join(FIXTURES, process.env.SONG || 'clicks.wav');
function log(...a) { console.log(`[${new Date().toISOString().slice(11, 23)}]`, ...a); }

async function enableSemantics(page) {
  await page.waitForSelector('flt-semantics-placeholder', { state: 'attached', timeout: 90000 });
  await page.evaluate(() => document.querySelector('flt-semantics-placeholder').click());
  await page.waitForTimeout(800);
}
async function semanticsText(page) {
  return page.evaluate(() => {
    const host = document.querySelector('flt-semantics-host');
    if (!host) return '';
    const parts = [];
    host.querySelectorAll('*').forEach((el) => {
      const l = el.getAttribute('aria-label');
      if (l) parts.push(l);
      if (el.childElementCount === 0 && el.textContent) parts.push(el.textContent);
    });
    return parts.join(' | ');
  });
}
async function waitForText(page, re, timeout = 20000) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    if (re.test(await semanticsText(page))) return;
    await page.waitForTimeout(250);
  }
  throw new Error(`Timed out waiting for ${re}`);
}

// Instrumentation: record WebAudio source starts and <audio> elements, and
// expose a real wall clock that ignores the patched Date.now.
const instrument = (skewMs) => {
  const realNow = Date.now.bind(Date);
  window.__realNow = () => performance.timeOrigin + performance.now();
  if (skewMs) Date.now = () => realNow() + skewMs;
  window.__sources = [];
  const origStart = AudioBufferSourceNode.prototype.start;
  AudioBufferSourceNode.prototype.start = function (when = 0, offset = 0, ...rest) {
    window.__sources.push({ node: this, ctx: this.context, when, offset });
    let ended = false;
    this.addEventListener('ended', () => { ended = true; });
    window.__sources[window.__sources.length - 1].isEnded = () => ended;
    return origStart.call(this, when, offset, ...rest);
  };
  window.__media = new Set();
  const origPlay = HTMLMediaElement.prototype.play;
  HTMLMediaElement.prototype.play = function () { window.__media.add(this); return origPlay.call(this); };
};

// Song position minus real wall time (ms): constant while playing in sync.
async function phase(page, kind) {
  return page.evaluate((kind) => {
    const now = window.__realNow();
    if (kind === 'host') {
      const s = [...window.__sources].reverse().find((x) => !x.isEnded());
      if (!s) return null;
      const ts = s.ctx.getOutputTimestamp();
      // Context time audible right now (render time minus output latency).
      const t = window.__AUDIBLE ? ts.contextTime + (performance.now() - ts.performanceTime) / 1000 : s.ctx.currentTime;
      window.__lat = { out: s.ctx.outputLatency, base: s.ctx.baseLatency, gap: s.ctx.currentTime - t };
      if (t < s.when) return null;
      return (s.offset + (t - s.when)) * 1000 - now;
    }
    if (kind === 'video') {
      const v = [...window.__media].find((m) => m.tagName === 'VIDEO' && !m.paused);
      return v ? v.currentTime * 1000 - now : null;
    }
    const el = [...window.__media].find((m) => !m.paused && m.readyState >= 2);
    if (!el) return null;
    return el.currentTime * 1000 - now;
  }, kind);
}

async function samplePhases(pages, n = 15) {
  const out = {};
  for (const [name] of pages) out[name] = [];
  for (let i = 0; i < n; i++) {
    for (const [name, page, kind] of pages) {
      const v = await phase(page, kind);
      if (v != null) out[name].push(v);
    }
    await pages[0][1].waitForTimeout(200);
  }
  const med = (a) => { const s = [...a].sort((x, y) => x - y); return s.length ? s[s.length >> 1] : null; };
  const res = {};
  for (const [name, arr] of Object.entries(out)) res[name] = med(arr);
  return res;
}

require('fs').mkdirSync(OUT, { recursive: true });

module.exports = {
  chromium, path, BASE, OUT, SONG, log, enableSemantics, semanticsText, waitForText,
  instrument, phase, samplePhases,
};
